package Hello_world;
/* write a java code to print 11111
 *                            22222
 *                            33333
 *                            44444
 *                            55555
 */
                              
public class A003_pattern2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n=5;
		for (int i = 1; i <=n; i++) {
			for (int j = 1; j <=n; j++) {
				System.out.print(i);
				
			}
			System.out.println();
			
		}
		
		

	}

}
